/** Discovery of a downloadable healthsites.io extract.
 *
 *  This is discovery in the sense experiment 39 settled: it resolves a location and yields a
 *  request, never bytes. healthsites.io sends no `access-control-allow-origin`, so the
 *  application cannot fetch it and a proxy is excluded by experiment 32's precedent. The
 *  practitioner's own browser performs the download, which CORS does not govern.
 *
 *  **The API key never becomes a value.** `download-evidence` serialises the whole run result
 *  into a shareable receipt, so a URL carrying the key would leak there. At run time this node
 *  only checks that the credential *resolves*; the URL is built at click time from the live
 *  session and discarded. See docs/experiments/30-local-credential-files.md. */
import type {AreaValue,Receipt,RemoteRequest} from './results.js';
import type {PointCollection,PointFeature} from './types.js';
import type {WorkflowNode} from './types.js';

export const HEALTHSITES_ORIGIN='https://healthsites.io';
export const HEALTHSITES_PROVIDER='healthsites';
export const HEALTHSITES_KINDS=['hospital','clinic','doctors','pharmacy','dentist','laboratory'] as const;

/** Resolves a secret for one credential reference, or throws. Supplied by the application so the
 *  session stays in the tab and out of the workflow. */
export type CredentialResolver=(ref:string,provider:string,origin:string)=>string;

export const HEALTHSITES_LINKS=[
  {label:'Open Database License (ODbL) 1.0',href:'https://opendatacommons.org/licenses/odbl/1-0/'},
  {label:'healthsites.io terms of use',href:'https://github.com/healthsites/healthsites/wiki/Healthsites---terms-of-use'},
  {label:'OpenStreetMap copyright and attribution',href:'https://www.openstreetmap.org/copyright'},
];

export const ODBL_ATTRIBUTION='Health facility data \u00a9 healthsites.io contributors and \u00a9 OpenStreetMap contributors, under the Open Database License (ODbL). Redistributing a database derived from it obliges you to offer that under ODbL and to keep this attribution.';

const text=(value:unknown)=>typeof value==='string'?value.trim():'';

/** Draft validation, run on every edit. A freshly added node has no credential and no country
 *  and must still be a valid draft, or it cannot be added at all — the mistake experiment 48
 *  recorded and this repeated. Only what is always wrong is checked here. */
export function validateHealthsitesNode(node:WorkflowNode<'healthsites_discovery'>):void{
  for(const kind of node.params.kinds||[])
    if(!(HEALTHSITES_KINDS as readonly string[]).includes(kind))
      throw new Error(`"${kind}" is not a healthsites facility kind.`);
  if(text(node.params.country).length>60)throw new Error('Use a country name of 60 characters or fewer.');
}

/** What must hold to run, checked when the node executes rather than when it is edited. */
export function requireRunnableHealthsites(node:WorkflowNode<'healthsites_discovery'>):void{
  validateHealthsitesNode(node);
  if(!text(node.params.credentialRef))
    throw new Error('Choose the credential for Find healthsites facilities. Unlock your credential file first; this node stores the reference, never the key.');
  if(!text(node.params.country)&&!node.params.useArea)
    throw new Error('Choose a country for Find healthsites facilities, or tick the study-area option and connect one.');
}

/** The extent healthsites expects: a lon/lat box, comma separated. */
export function extentOf(area:AreaValue):string{
  const bounds=area.bounds;
  if(!bounds||bounds.length!==4||!bounds.every(Number.isFinite))
    throw new Error('The connected study area has no usable extent.');
  return bounds.map(v=>v.toFixed(5)).join(',');
}

export function healthsitesRequest(
  node:WorkflowNode<'healthsites_discovery'>, area:AreaValue|undefined, resolve:CredentialResolver,
):{value:{kind:'remote-request';rows:never[];centers:never[]};request:RemoteRequest;receipt:Receipt}{
  requireRunnableHealthsites(node);
  const ref=text(node.params.credentialRef);
  // Check only. The secret is resolved again at click time and never stored, returned or logged.
  resolve(ref,HEALTHSITES_PROVIDER,HEALTHSITES_ORIGIN);
  if(node.params.useArea&&!area)
    throw new Error('Connect a study area, or choose a country instead.');
  const extent=node.params.useArea&&area?extentOf(area):null;
  const country=extent?'':text(node.params.country);
  const kinds=[...(node.params.kinds||[])];
  const query:Record<string,string>={page:'1'};
  if(extent)query.extent=extent; else query.country=country;

  const request:RemoteRequest={nodeId:node.id,provider:HEALTHSITES_PROVIDER,origin:HEALTHSITES_ORIGIN,
    credentialRef:ref,scope:extent?`study area ${extent}`:country,kinds,
    licence:'ODbL',attribution:ODBL_ATTRIBUTION,links:HEALTHSITES_LINKS,query};
  const activity=`<urn:fieldwork:run:${node.id}:healthsites>`;
  // The licence is an IRI rather than a label, so it resolves and can be compared. DCAT carries
  // the thing being requested; Dublin Core carries the terms that attach to it.
  const facts=`@prefix fw: <urn:fieldwork:>.\n@prefix prov: <http://www.w3.org/ns/prov#>.\n@prefix dcterms: <http://purl.org/dc/terms/>.\n@prefix dcat: <http://www.w3.org/ns/dcat#>.\n`
    +`${activity} a fw:RemoteAssetRequest, prov:Activity; `
    +`fw:requestOrigin <${HEALTHSITES_ORIGIN}>; `
    +`fw:credentialReference ${JSON.stringify(ref)}; `
    +(extent?`fw:requestExtent ${JSON.stringify(extent)}; `:`fw:requestCountry ${JSON.stringify(country)}; `)
    +`fw:requestedKinds ${JSON.stringify(kinds.join(', ')||'all')}; `
    +`prov:used <${HEALTHSITES_ORIGIN}#dataset>.\n`
    +`<${HEALTHSITES_ORIGIN}#dataset> a dcat:Dataset; `
    +`dcterms:title "healthsites.io health facilities"; `
    +`dcterms:license <https://opendatacommons.org/licenses/odbl/1-0/>; `
    +`dcterms:source <https://www.openstreetmap.org/copyright>; `
    +`dcterms:rights ${JSON.stringify(ODBL_ATTRIBUTION)}.\n`;
  return {value:{kind:'remote-request',rows:[],centers:[]},request,receipt:{nodeId:node.id,kind:'computation',facts,input:facts,rules:'',conclusions:[],
    method:'Resolved a download location and checked that the named credential is available. The licence and its obligations are presented at the moment of download, and the download proceeds only if the practitioner accepts them. Yields a request, never data: this prototype cannot fetch healthsites.io, which sends no cross-origin header, so your own browser performs the download. The key is never part of this result, and nothing here records what you downloaded or verifies that the file you later import is the file this described.'}};
}

/** Built at click time, in the dialog, from the live session. Never stored or returned to the
 *  workflow: the run receipt is shareable and the key must not reach it. */
export function healthsitesUrl(request:RemoteRequest,resolve:CredentialResolver):string{
  const secret=resolve(request.credentialRef,request.provider,request.origin);
  const url=new URL('/api/v3/facilities/',request.origin);
  for(const [key,value] of Object.entries(request.query))url.searchParams.set(key,value);
  url.searchParams.set('api-key',secret);
  return url.toString();
}

/** Parse a healthsites download into a point layer.
 *
 *  Accepts the API's own JSON array and an ordinary GeoJSON FeatureCollection, because the map
 *  page and the API hand back different shapes of the same thing. Records are dropped, and
 *  counted, when they carry no name, no coordinates or a kind that was not asked for: a facility
 *  without a location is not a facility this can place, and silently keeping it would overstate
 *  coverage. Nothing is invented — no centroid is guessed and no kind inferred. */
export interface ParsedFacilities {collection:PointCollection; kept:number;
  dropped:{kind:number;coordinates:number;name:number}}

export function parseHealthsites(text:string,kinds:readonly string[]):ParsedFacilities{
  let raw:unknown;
  try{raw=JSON.parse(text);}catch{throw new Error('That file is not JSON. Download the GeoJSON or JSON export, not the shapefile or KML.');}
  const records=Array.isArray(raw)?raw
    :raw&&typeof raw==='object'&&Array.isArray((raw as {features?:unknown[]}).features)?(raw as {features:unknown[]}).features
    :null;
  if(!records)throw new Error('That file holds no facility records. Expected a JSON array or a GeoJSON FeatureCollection.');
  const wanted=new Set(kinds);
  const dropped={kind:0,coordinates:0,name:0};
  const features:PointFeature[]=[];
  for(const record of records as Record<string,unknown>[]){
    const attributes=(record.attributes||record.properties||{}) as Record<string,unknown>;
    const kind=String(attributes.healthcare||attributes.amenity||'').trim();
    const geometry=(record.centroid||record.geometry) as {type?:string;coordinates?:unknown}|undefined;
    const coordinates=Array.isArray(geometry?.coordinates)?geometry!.coordinates as number[]:null;
    const name=String(attributes.name||'').trim();
    if(wanted.size&&!wanted.has(kind)){dropped.kind++;continue;}
    if(!coordinates||coordinates.length<2||!coordinates.slice(0,2).every(Number.isFinite)){dropped.coordinates++;continue;}
    if(!name){dropped.name++;continue;}
    const id=record.osm_type&&record.osm_id?`${record.osm_type}/${record.osm_id}`:String(record.id??`facility-${features.length+1}`);
    features.push({type:'Feature',id,properties:{name,kind,
      ...(typeof attributes.completeness==='number'?{completeness:attributes.completeness}:{}),
      ...(typeof record.completeness==='number'?{completeness:record.completeness}:{})},
      geometry:{type:'Point',coordinates:[Number(coordinates[0]),Number(coordinates[1])]}});
  }
  if(!features.length)throw new Error(`No facilities in that file matched ${kinds.join(', ')||'the requested kinds'}. Check the kinds, or download a wider extract.`);
  return {collection:{type:'FeatureCollection',features},kept:features.length,dropped};
}

/** The acquired layer, for a node whose download has been handed back.
 *
 *  The receipt names the file, its digest and the counts kept and dropped. That digest is the
 *  thing a request alone could never carry: it says which bytes this layer came from, so a reader
 *  can tell whether two runs used the same extract. The licence travels with it, because ODbL is
 *  share-alike and a workflow that used this data has to say so in its facts. */
export function healthsitesFacilities(
  node:WorkflowNode<'healthsites_discovery'>, runId:string,
):{value:PointCollection&{sourceNodeId:string};receipt:Receipt}{
  const got=node.params.retrieved, data=node.params.data;
  if(!got||!data)throw new Error(
    'Find healthsites facilities has no data yet. Open it, press Apply, accept the licence, then hand the downloaded file back.');
  const entity=`<urn:fieldwork:run:${runId}:${node.id}:facilities>`;
  const facts=`@prefix fw: <urn:fieldwork:>.\n@prefix prov: <http://www.w3.org/ns/prov#>.\n@prefix dcterms: <http://purl.org/dc/terms/>.\n@prefix dcat: <http://www.w3.org/ns/dcat#>.\n`
    +`${entity} a fw:PointDataset, prov:Entity; `
    +`fw:facilityCount ${data.features.length}; `
    +`fw:sourceFileName ${JSON.stringify(got.filename)}; `
    +`fw:sourceFileDigest ${JSON.stringify(`sha256:${got.sha256}`)}; `
    +`fw:sourceFileBytes ${got.bytes}; `
    +`dcterms:license <https://opendatacommons.org/licenses/odbl/1-0/>; `
    +`dcterms:source <https://www.openstreetmap.org/copyright>; `
    +`dcterms:rights ${JSON.stringify(ODBL_ATTRIBUTION)}; `
    +`prov:wasDerivedFrom <${HEALTHSITES_ORIGIN}#dataset>.\n`;
  const dropped=got.dropped.kind+got.dropped.coordinates+got.dropped.name;
  return {value:{...structuredClone(data),sourceNodeId:node.id},receipt:{nodeId:node.id,kind:'computation',
    facts,input:facts,rules:'',conclusions:[],
    method:`Read ${got.kept} facilities from ${got.filename} (sha256 ${got.sha256.slice(0,12)}…, ${got.bytes} bytes), downloaded by the practitioner's own browser after accepting the Open Database License. `
      +(dropped?`Dropped ${dropped} records: ${got.dropped.kind} of a kind that was not requested, ${got.dropped.coordinates} without usable coordinates, ${got.dropped.name} without a name. `:'Dropped no records. ')
      +'The digest identifies the file these points came from; it does not attest that the file is what healthsites.io served, which this prototype cannot check because the service sends no cross-origin header and the response is unreadable to the page. The licence is share-alike and travels with the data.'}};
}
